    deriv_title: 'Why is the area under v–t the displacement?',
    deriv_intro: 'For uniform acceleration the v–t graph is a straight line from u to v. The area under it is a rectangle plus a triangle:',
    deriv_1: 'Rectangle: width t, height u, so its area is u × t (the distance covered at the starting velocity).',
    deriv_2: 'Triangle: base t, height (v − u) = at, so its area is ½ × t × at = ½at² (the extra distance because of speeding up).',
