    w1_t: 'Distance and displacement',
    w1_d: 'Distance is the total length of the path travelled. Displacement is the straight-line change in position from start to end, and it has a direction.',
    w1_e: 'Example: walk 30 m to the shop and 30 m back. Distance = 60 m, displacement = 0.',
    w2_t: 'Speed and velocity',
    w2_d: 'Speed = distance ÷ time; it has only a size. Velocity = displacement ÷ time; it has a size and a direction. In this app a negative velocity means moving back towards the start.',
    w2_e: 'Example: a car going east at 20 m/s and one going west at 20 m/s have the same speed but different velocities.',
    w3_t: 'Uniform and non-uniform motion',
    w3_d: 'Uniform motion covers equal distances in equal intervals of time: the d–t graph is a straight line and the v–t graph is flat. In non-uniform motion the speed keeps changing and the d–t graph bends.',
    w3_e: 'Example: a train cruising at a steady 60 km/h is uniform motion; a bus in city traffic is non-uniform motion.',
    w4_t: 'Average speed',
    w4_d: 'Average speed = total distance ÷ total time, even when the speed kept changing on the way. Average velocity = total displacement ÷ total time.',
    w4_e: 'Example: Delhi to Agra is about 200 km. Done in 2.5 hours, the average speed is 200 ÷ 2.5 = 80 km/h (about 22 m/s).',
    w5_t: 'Acceleration',
    w5_d: 'Acceleration = change in velocity ÷ time, in m/s². It is the slope of the v–t graph. Positive means speeding up (in the forward direction); negative means slowing down, also called retardation.',
    w5_e: 'Example: 0 to 20 m/s in 10 s is an acceleration of 20 ÷ 10 = 2 m/s².',
    w6_t: 'Uniform circular motion',
    w6_d: 'An object going round a circle at a steady speed is still accelerating, because its direction keeps changing. Its speed is v = 2πr ÷ T, where r is the radius and T is the time for one full round.',
    w6_e: 'Example: a toy train on a circular track of radius 2 m takes 4 s per round: v = 2 × 3.14 × 2 ÷ 4 ≈ 3.14 m/s.',
