    inside_1: 'টেবিলের প্রতিটি সারি গতির একটি অংশ। সমবেগে দূরত্ব = v × t। বেগ u থেকে v পর্যন্ত সমানভাবে বদলালে ত্বরণ a = (v − u) ÷ t এবং অতিক্রান্ত দূরত্ব = (u + v) ÷ 2 × t।',
    inside_2: 'd–t গ্রাফ শুরু থেকে মাপা অবস্থান দেখায়। এর ঢাল (উচ্চতা ÷ ভূমি) হলো বেগ: খাড়া রেখা মানে দ্রুত, সমতল রেখা মানে থেমে আছে, নিচে নামা রেখা মানে পিছনে চলা।',
    inside_3: 'v–t গ্রাফে ঢাল হলো ত্বরণ, আর রেখা ও সময়-অক্ষের মাঝের ক্ষেত্রফল হলো সরণ। অক্ষের উপরের ক্ষেত্রফল সামনে (+) ধরা হয়, নিচেরটা পিছনে (−)।',
    inside_4: 'a–t গ্রাফ প্রতিটি অংশে সমতল, কারণ প্রতিটি অংশে ত্বরণ ধ্রুব (সমবেগে শূন্য)।',
