    how1: 'একটি তৈরি উদাহরণ বেছে নাও বা টেবিল বদলাও: প্রতিটি সারি যাত্রার একটি অংশ। “চালাও” চাপো আর যান ও তিনটি গ্রাফকে একসঙ্গে চলতে দেখো।',
