    inside_title: 'आत काय घडते आहे?',
    inside_1: 'तक्त्याची प्रत्येक ओळ गतीचा एक भाग आहे. एकसमान वेगाने अंतर = v × t. वेग u पासून v पर्यंत एकसमानपणे बदलतो तेव्हा त्वरण a = (v − u) ÷ t आणि कापलेले अंतर = (u + v) ÷ 2 × t.',
    inside_2: 'd–t आलेख सुरुवातीपासून मोजलेले स्थान दाखवतो. त्याचा उतार (उंची ÷ रुंदी) म्हणजे वेग: उभी रेषा म्हणजे जलद, सपाट रेषा म्हणजे थांबलेले, खाली जाणारी रेषा म्हणजे मागे जाणे.',
    inside_3: 'v–t आलेखावर उतार म्हणजे त्वरण, आणि रेषा व काळ-अक्ष यांमधील क्षेत्रफळ म्हणजे विस्थापन. अक्षावरील क्षेत्रफळ पुढे (+) धरले जाते, खालील मागे (−).',
    inside_4: 'a–t आलेख प्रत्येक भागात सपाट असतो, कारण प्रत्येक भागात त्वरण स्थिर असते (एकसमान वेगाला शून्य).',
