    conv_examples: 'उपयोगी मूल्ये: 36 km/h = 10 m/s, 72 km/h = 20 m/s, 90 km/h = 25 m/s, 108 km/h = 30 m/s.',
    deriv_title: 'v–t खालील क्षेत्रफळ म्हणजे विस्थापन का?',
    deriv_intro: 'एकसमान त्वरणात v–t आलेख u पासून v पर्यंत सरळ रेषा असतो. त्याखालील क्षेत्रफळ = एक आयत + एक त्रिकोण:',
    deriv_1: 'आयत: रुंदी t, उंची u, म्हणून क्षेत्रफळ u × t (आरंभीच्या वेगाने कापलेले अंतर).',
    deriv_2: 'त्रिकोण: पाया t, उंची (v − u) = at, म्हणून क्षेत्रफळ ½ × t × at = ½at² (वेग वाढल्यामुळे मिळालेले जास्तीचे अंतर).',
    deriv_3: 'एकूण क्षेत्रफळ = ut + ½at² = s. हेच गतीचे दुसरे समीकरण.',
    deriv_4: 'हेच चित्र एक समलंब चौकोनही आहे, ज्यातून s = (u + v) ÷ 2 × t मिळते; त्यात t = (v − u) ÷ a ठेवल्यास v² = u² + 2as मिळते.',
