    w1_t: 'अंतर आणि विस्थापन',
    w1_d: 'अंतर म्हणजे कापलेल्या मार्गाची एकूण लांबी. विस्थापन म्हणजे सुरुवातीपासून शेवटपर्यंत स्थानातील सरळ रेषेतील बदल, आणि त्याला दिशा असते.',
    w1_e: 'उदाहरण: दुकानापर्यंत 30 m जा आणि 30 m परत या. अंतर = 60 m, विस्थापन = 0.',
    w2_t: 'चाल आणि वेग',
    w2_d: 'चाल = अंतर ÷ काळ; तिला फक्त परिमाण असते. वेग = विस्थापन ÷ काळ; त्याला परिमाण आणि दिशा दोन्ही असतात. या अ‍ॅपमध्ये ऋण वेग म्हणजे सुरुवातीकडे परत जाणे.',
