    w3_t: 'एकसमान आणि असमान गती',
    w3_d: 'एकसमान गतीत समान काळात समान अंतर कापले जाते: d–t आलेख सरळ रेषा असतो आणि v–t आलेख सपाट. असमान गतीत चाल बदलत राहते आणि d–t आलेख वाकतो.',
