    w5_e: 'उदाहरण: 10 s मध्ये 0 पासून 20 m/s होणे = 20 ÷ 10 = 2 m/s² चे त्वरण.',
    w6_t: 'एकसमान वर्तुळाकार गती',
    w6_d: 'स्थिर चालीने वर्तुळात फिरणारी वस्तूही त्वरित असते, कारण तिची दिशा सतत बदलते. तिची चाल v = 2πr ÷ T, जिथे r त्रिज्या आणि T एका पूर्ण फेरीचा काळ.',
