    deriv_intro: 'એકસમાન પ્રવેગમાં v–t આલેખ u થી v સુધીની સીધી રેખા છે. તેની નીચેનું ક્ષેત્રફળ = એક લંબચોરસ + એક ત્રિકોણ:',
