    w4_e: 'ઉદાહરણ: દિલ્હીથી આગ્રા લગભગ 200 km છે. 2.5 કલાકમાં કાપતાં સરેરાશ ઝડપ = 200 ÷ 2.5 = 80 km/h (લગભગ 22 m/s).',
