    w6_e: 'ઉદાહરણ: 2 m ત્રિજ્યાના ગોળ પાટા પર રમકડાની ટ્રેન એક ચક્કરમાં 4 s લે છે: v = 2 × 3.14 × 2 ÷ 4 ≈ 3.14 m/s.',
