    circ_r: 'ત્રિજ્યા r (m)', circ_T: 'આવર્તકાળ T (s)',
    circ_need: '0 થી મોટી ત્રિજ્યા અને આવર્તકાળ લખો.',
    howto_title: 'કેવી રીતે વાપરવું / વર્ગ માટે વિચારો',
    how1: 'કોઈ તૈયાર ઉદાહરણ પસંદ કરો અથવા કોષ્ટક બદલો: દરેક હરોળ મુસાફરીનો એક ભાગ છે. “ચલાવો” દબાવો અને વાહન તથા ત્રણેય આલેખને સાથે ચાલતા જુઓ.',
    how2: 'ઢાળ માપક ચાલુ કરીને બે માર્કર ખેંચો: d–t પર ઢાળ એટલે વેગ, v–t પર પ્રવેગ. a–t આલેખ સાથે સરખાવો.',
    how3: '“ઉપર ફેંકેલો દડો” અજમાવો: વેગનું ચિહ્ન બદલાય છે, v–t નીચેનું ક્ષેત્રફળ પહેલાં + પછી − થાય છે, અને સ્થાનાંતર 0 પર પાછું આવે છે પણ અંતર નહીં.',
    how4: '“ગતિનાં સમીકરણો” માં u, v, a, t, s માંથી કોઈ પણ ત્રણ પર ટિક કરો. પૃથ્વી, ચંદ્ર કે મંગળનું g વાપરવા મુક્ત પતન પર જાઓ.',
    how5: 'વર્ગ પ્રવૃત્તિ: એક વિદ્યાર્થી લોબીમાં મુસાફરી કરી બતાવે (ચાલવું, થોભવું, પાછા આવવું). વર્ગ અહીં તેનું કોષ્ટક બનાવે અને “ચલાવો” દબાવતાં પહેલાં કાગળ પર d–t આલેખ દોરે.',
    how6: 'સ્માર્ટબોર્ડ પર ટીમોમાં આલેખ ક્વિઝ રમો, અથવા ગૃહકાર્ય માટે વર્કશીટ (જવાબ ચાવી સાથે) છાપો.'
