    inside_1: 'ਸਾਰਣੀ ਦੀ ਹਰ ਕਤਾਰ ਗਤੀ ਦਾ ਇੱਕ ਹਿੱਸਾ ਹੈ। ਇੱਕਸਾਰ ਵੇਗ ’ਤੇ ਦੂਰੀ = v × t। ਜਦੋਂ ਵੇਗ u ਤੋਂ v ਤੱਕ ਇੱਕਸਾਰ ਬਦਲਦਾ ਹੈ, ਤਾਂ ਪ੍ਰਵੇਗ a = (v − u) ÷ t ਅਤੇ ਤੈਅ ਕੀਤੀ ਦੂਰੀ = (u + v) ÷ 2 × t।',
