    slope_title: 'சாய்வு கருவி', slope_on: 'குறிகளைக் காட்டு',
    slope_hint: 'வரைபடத்தில் உள்ள இரு குறிகளையும் இழுங்கள் (அல்லது நேரங்களை உள்ளிடுங்கள்). அவற்றுக்கு இடையிலான கோட்டின் சாய்வு = உயரம் ÷ அகலம்.',
