    g_at: 'త్వరణం–కాలం (a–t)', g_at_hint: 'వైశాల్యం = వేగంలో మార్పు',
    ax_t: 't (s)', ax_d: 'd (m)', ax_v: 'v (m/s)', ax_a: 'a (m/s²)',
    area_pos: 'అక్షం పైన వైశాల్యం (ముందుకు):', area_neg: 'అక్షం కింద వైశాల్యం (వెనక్కి):', area_total: 'స్థానభ్రంశం =',
    slope_title: 'వాలు సాధనం', slope_on: 'మార్కర్లు చూపించు',
    slope_hint: 'గ్రాఫ్‌పై రెండు మార్కర్లను లాగండి (లేదా సమయాలు టైప్ చేయండి). వాటి మధ్య రేఖ వాలు = ఎత్తు ÷ వెడల్పు.',
    slope_which: 'ఏ గ్రాఫ్', slope_on_dt: 'd–t పై', slope_on_vt: 'v–t పై',
    slope_word: 'వాలు', marker: 'మార్కర్',
    slope_same: 'మార్కర్లను దూరంగా జరపండి: రెండూ ఒకే సమయంలో ఉన్నాయి.',
    slope_is_v: 'd–t గ్రాఫ్ వాలు = వేగం', slope_is_a: 'v–t గ్రాఫ్ వాలు = త్వరణం',
    slope_read_v: 'మార్కర్ల మధ్య వస్తువు ప్రతి సెకనుకు (సగటున) {n} m వెళ్తుంది.',
    slope_read_a: 'మార్కర్ల మధ్య వేగం ప్రతి సెకనుకు (సగటున) {n} m/s మారుతుంది.',
    reset_done: 'నమూనా ఉదాహరణ తిరిగి వచ్చింది.',
    inside_title: 'లోపల ఏం జరుగుతోంది?',
    inside_1: 'పట్టికలోని ప్రతి వరుస చలనంలో ఒక భాగం. స్థిర వేగంలో దూరం = v × t. వేగం u నుండి v వరకు సమంగా మారినప్పుడు త్వరణం a = (v − u) ÷ t, ప్రయాణించిన దూరం = (u + v) ÷ 2 × t.',
    inside_2: 'd–t గ్రాఫ్ మొదలు నుండి కొలిచిన స్థానాన్ని చూపిస్తుంది. దాని వాలు (ఎత్తు ÷ వెడల్పు) వేగం: నిటారు రేఖ అంటే వేగంగా, చదునైన రేఖ అంటే ఆగి ఉంది, కిందకు దిగే రేఖ అంటే వెనక్కి వెళ్తోంది.',
    inside_3: 'v–t గ్రాఫ్‌లో వాలు త్వరణం, రేఖకు కాల అక్షానికి మధ్య వైశాల్యం స్థానభ్రంశం. అక్షం పైన వైశాల్యం ముందుకు (+), కింద వైశాల్యం వెనక్కి (−) లెక్కిస్తారు.',
    inside_4: 'ప్రతి భాగంలో త్వరణం స్థిరం కాబట్టి (స్థిర వేగంలో సున్నా) a–t గ్రాఫ్ ప్రతి భాగంలో చదునుగా ఉంటుంది.',
