    eq_mode: 'సాధించే విధానం', mode_general: 'ఏ చలనమైనా', mode_ff: 'స్వేచ్ఛా పతనం (గురుత్వం)',
    ff_where: 'ఎక్కడ?', g_earth: 'భూమి', g_moon: 'చంద్రుడు', g_mars: 'అంగారకుడు',
    ff_dir: 'దిశ', ff_down: 'కిందకు పడటం', ff_up: 'పైకి విసరడం',
    ff_note_down: 'కింది దిశను ధనాత్మకంగా తీసుకున్నాం: a = g = {g} m/s², s అంటే పడిన ఎత్తు. నిశ్చల స్థితి నుండి వదిలితే u = 0.',
    ff_note_up: 'పై దిశను ధనాత్మకంగా తీసుకున్నాం: a = −g = −{g} m/s², కాబట్టి వస్తువు నెమ్మదిస్తుంది. అత్యున్నత బిందువు వద్ద v = 0.',
    knowns_label: 'తెలిసినవి టిక్ చేయండి:',
    q_u: 'తొలి వేగం', q_v: 'తుది వేగం', q_a: 'త్వరణం', q_t: 'కాలం', q_s: 'స్థానభ్రంశం (దూరం)',
