    inside_title: 'ಒಳಗೆ ಏನಾಗುತ್ತಿದೆ?',
    inside_1: 'ಕೋಷ್ಟಕದ ಪ್ರತಿ ಸಾಲು ಚಲನೆಯ ಒಂದು ಭಾಗ. ಸ್ಥಿರ ವೇಗದಲ್ಲಿ ದೂರ = v × t. ವೇಗ u ನಿಂದ v ವರೆಗೆ ಸಮವಾಗಿ ಬದಲಾದಾಗ ವೇಗೋತ್ಕರ್ಷ a = (v − u) ÷ t ಮತ್ತು ಕ್ರಮಿಸಿದ ದೂರ = (u + v) ÷ 2 × t.',
    inside_2: 'd–t ಗ್ರಾಫ್ ಆರಂಭದಿಂದ ಅಳೆದ ಸ್ಥಾನವನ್ನು ತೋರಿಸುತ್ತದೆ. ಅದರ ಇಳಿಜಾರು (ಎತ್ತರ ÷ ಅಗಲ) ವೇಗ: ಕಡಿದಾದ ರೇಖೆ ಎಂದರೆ ವೇಗವಾಗಿ, ಸಮತಲ ರೇಖೆ ಎಂದರೆ ನಿಂತಿದೆ, ಕೆಳಗಿಳಿಯುವ ರೇಖೆ ಎಂದರೆ ಹಿಂದಕ್ಕೆ ಚಲಿಸುತ್ತಿದೆ.',
    inside_3: 'v–t ಗ್ರಾಫ್‌ನಲ್ಲಿ ಇಳಿಜಾರು ವೇಗೋತ್ಕರ್ಷ, ರೇಖೆ ಮತ್ತು ಕಾಲ-ಅಕ್ಷದ ನಡುವಿನ ವಿಸ್ತೀರ್ಣ ಸ್ಥಾನಪಲ್ಲಟ. ಅಕ್ಷದ ಮೇಲಿನ ವಿಸ್ತೀರ್ಣ ಮುಂದಕ್ಕೆ (+), ಕೆಳಗಿನದು ಹಿಂದಕ್ಕೆ (−) ಎಂದು ಲೆಕ್ಕ.',
