    deriv_intro: 'ಏಕರೂಪ ವೇಗೋತ್ಕರ್ಷದಲ್ಲಿ v–t ಗ್ರಾಫ್ u ನಿಂದ v ವರೆಗಿನ ಸರಳ ರೇಖೆ. ಅದರ ಕೆಳಗಿನ ವಿಸ್ತೀರ್ಣ = ಒಂದು ಆಯತ + ಒಂದು ತ್ರಿಭುಜ:',
    deriv_1: 'ಆಯತ: ಅಗಲ t, ಎತ್ತರ u, ಆದ್ದರಿಂದ ವಿಸ್ತೀರ್ಣ u × t (ಆರಂಭಿಕ ವೇಗದಲ್ಲಿ ಕ್ರಮಿಸಿದ ದೂರ).',
