    segments: 'ചലനത്തിന്റെ ഭാഗങ്ങൾ',
    segments_hint: 'ഓരോ വരിയും ഒരു ഭാഗമാണ്: t സെക്കൻഡ് സ്ഥിര പ്രവേഗത്തിൽ സഞ്ചരിക്കുക, അല്ലെങ്കിൽ t സെക്കൻഡിൽ പ്രവേഗം u മുതൽ v വരെ ഒരേ നിരക്കിൽ മാറ്റുക. ഋണ പ്രവേഗം എന്നാൽ പിന്നോട്ട് പോകുക.',
    col_type: 'തരം', col_u: 'u (m/s)', col_v: 'v (m/s)', col_t: 't (s)', col_a: 'a (m/s²)', col_dist: 'ദൂരം (m)',
    type_const: 'സ്ഥിര പ്രവേഗം', type_accel: 'പ്രവേഗം മാറ്റുക',
    add_const: 'സ്ഥിര പ്രവേഗം', add_accel: 'വേഗം കൂട്ടുക / കുറയ്ക്കുക',
    del_row: 'ഈ ഭാഗം നീക്കം ചെയ്യുക',
    seg_jump_note: 'ശ്രദ്ധിക്കുക: രണ്ട് ഭാഗങ്ങൾക്കിടയിൽ പ്രവേഗം പെട്ടെന്ന് ചാടുന്നു. യഥാർത്ഥ വാഹനങ്ങൾക്ക് അത് കഴിയില്ല; ഒരു ഭാഗത്തിന്റെ u മുൻ ഭാഗത്തിന്റെ v ക്ക് തുല്യമാക്കൂ.',
    seg_turn_note: 'അടയാളപ്പെടുത്തിയ ഭാഗം v = 0 കടന്നുപോകുന്നു: വസ്തു തിരിഞ്ഞ് പിന്നോട്ട് പോകുന്നു.',
