    time_slider: 'സമയം',
    results_title: 'മുഴുവൻ ചലനത്തിന്റെ കണക്ക്',
    ro_time: 'ആകെ സമയം', ro_dist: 'ദൂരം (പാതയുടെ നീളം)', ro_disp: 'സ്ഥാനാന്തരം', ro_avgs: 'ശരാശരി വേഗം = ദൂരം ÷ സമയം', ro_avgv: 'ശരാശരി പ്രവേഗം = സ്ഥാനാന്തരം ÷ സമയം',
    ro_disp_f: 'അവസാന സ്ഥാനം {d} m',
    ro_note_back: 'വസ്തു കുറച്ച് സമയം പിന്നോട്ട് സഞ്ചരിച്ചു, അതിനാൽ സ്ഥാനാന്തരം ദൂരത്തെക്കാൾ കുറവും ശരാശരി പ്രവേഗം ശരാശരി വേഗത്തെക്കാൾ കുറവുമാണ്.',
    ro_note_same: 'വസ്തു ഒരേ ദിശയിൽ സഞ്ചരിച്ചു, അതിനാൽ ദൂരം = സ്ഥാനാന്തരം, ശരാശരി വേഗം = ശരാശരി പ്രവേഗം.',
    g_dt: 'ദൂരം–സമയം (d–t)', g_dt_hint: 'ചരിവ് = പ്രവേഗം',
    g_vt: 'പ്രവേഗം–സമയം (v–t)', g_vt_hint: 'ചരിവ് = ത്വരണം · വിസ്തീർണ്ണം = സ്ഥാനാന്തരം',
    g_at: 'ത്വരണം–സമയം (a–t)', g_at_hint: 'വിസ്തീർണ്ണം = പ്രവേഗത്തിലെ മാറ്റം',
