    slope_hint: 'ഗ്രാഫിലെ രണ്ട് മാർക്കറുകൾ വലിച്ചു നീക്കൂ (അല്ലെങ്കിൽ സമയം ടൈപ്പ് ചെയ്യൂ). അവയ്ക്കിടയിലെ രേഖയുടെ ചരിവ് = ഉയരം ÷ വീതി.',
