    slope_read_v: 'മാർക്കറുകൾക്കിടയിൽ വസ്തു ഓരോ സെക്കൻഡിലും (ശരാശരി) {n} m സഞ്ചരിക്കുന്നു.',
    slope_read_a: 'മാർക്കറുകൾക്കിടയിൽ പ്രവേഗം ഓരോ സെക്കൻഡിലും (ശരാശരി) {n} m/s മാറുന്നു.',
    reset_done: 'മാതൃകാ ഉദാഹരണം തിരികെ വന്നു.',
    inside_title: 'ഉള്ളിൽ എന്താണ് നടക്കുന്നത്?',
    inside_1: 'പട്ടികയിലെ ഓരോ വരിയും ചലനത്തിന്റെ ഒരു ഭാഗമാണ്. സ്ഥിര പ്രവേഗത്തിൽ ദൂരം = v × t. പ്രവേഗം u മുതൽ v വരെ ഒരേ നിരക്കിൽ മാറുമ്പോൾ ത്വരണം a = (v − u) ÷ t, സഞ്ചരിച്ച ദൂരം = (u + v) ÷ 2 × t.',
    inside_2: 'd–t ഗ്രാഫ് തുടക്കത്തിൽ നിന്ന് അളന്ന സ്ഥാനം കാണിക്കുന്നു. അതിന്റെ ചരിവ് (ഉയരം ÷ വീതി) പ്രവേഗമാണ്: കുത്തനെയുള്ള രേഖ എന്നാൽ വേഗത്തിൽ, പരന്ന രേഖ എന്നാൽ നിന്നിരിക്കുന്നു, താഴേക്ക് പോകുന്ന രേഖ എന്നാൽ പിന്നോട്ട് പോകുന്നു.',
    inside_3: 'v–t ഗ്രാഫിൽ ചരിവ് ത്വരണവും രേഖയ്ക്കും സമയ-അക്ഷത്തിനും ഇടയിലെ വിസ്തീർണ്ണം സ്ഥാനാന്തരവുമാണ്. അക്ഷത്തിന് മുകളിലെ വിസ്തീർണ്ണം മുന്നോട്ട് (+), താഴെയുള്ളത് പിന്നോട്ട് (−) ആയി കണക്കാക്കുന്നു.',
    inside_4: 'ഓരോ ഭാഗത്തും ത്വരണം സ്ഥിരമായതിനാൽ (സ്ഥിര പ്രവേഗത്തിൽ പൂജ്യം) a–t ഗ്രാഫ് ഓരോ ഭാഗത്തും പരന്നതാണ്.',
    eq_title: 'ചലന സമവാക്യങ്ങൾ',
    eq_intro: 'അറിയാവുന്ന മൂന്ന് അളവുകൾ ടിക്ക് ചെയ്ത് മൂല്യങ്ങൾ ടൈപ്പ് ചെയ്യൂ. ബാക്കി രണ്ടെണ്ണം, ഉപയോഗിച്ച സമവാക്യവും ഓരോ പടിയും സഹിതം, കണക്കാക്കും.',
    eq_mode: 'നിർധാരണ രീതി', mode_general: 'ഏത് ചലനവും', mode_ff: 'സ്വതന്ത്ര പതനം (ഗുരുത്വാകർഷണം)',
    ff_where: 'എവിടെ?', g_earth: 'ഭൂമി', g_moon: 'ചന്ദ്രൻ', g_mars: 'ചൊവ്വ',
    ff_dir: 'ദിശ', ff_down: 'താഴേക്ക് വീഴുന്നു', ff_up: 'മുകളിലേക്ക് എറിയുന്നു',
    ff_note_down: 'താഴേക്കുള്ള ദിശ ധനമായി എടുത്തിരിക്കുന്നു: a = g = {g} m/s², s വീണ ഉയരമാണ്. നിശ്ചലാവസ്ഥയിൽ നിന്ന് വിട്ടാൽ u = 0.',
    ff_note_up: 'മുകളിലേക്കുള്ള ദിശ ധനമായി എടുത്തിരിക്കുന്നു: a = −g = −{g} m/s², അതിനാൽ വസ്തു പതുക്കെയാകുന്നു. ഏറ്റവും ഉയർന്ന ബിന്ദുവിൽ v = 0.',
    knowns_label: 'അറിയാവുന്നവ ടിക്ക് ചെയ്യൂ:',
