    eq1_name: 'ഒന്നാം സമവാക്യം', eq2_name: 'രണ്ടാം സമവാക്യം', eq3_name: 'മൂന്നാം സമവാക്യം', eq4_name: 'ശരാശരി പ്രവേഗം × സമയം',
    err_need3: 'അഞ്ചിൽ കൃത്യം മൂന്ന് മൂല്യങ്ങൾ ടിക്ക് ചെയ്ത് പൂരിപ്പിക്കൂ (ഇപ്പോൾ {n} ഉണ്ട്).',
    err_only3: 'ഒരേ സമയം മൂന്ന് മൂല്യങ്ങൾ മാത്രമേ അറിയാവുന്നവയാകാൻ കഴിയൂ. ഒന്നിന്റെ ടിക്ക് മാറ്റൂ, ബാക്കി രണ്ടെണ്ണം ആപ്പ് കണക്കാക്കും.',
    err_t: 'സമയം 0-ൽ കൂടുതലായിരിക്കണം.',
    err_a0: 'a = 0, u = v ആയാൽ ചലനം സമചലനമാണ്, അതിനാൽ ഏത് സമയവും സാധ്യമാണ്. a ക്ക് പകരം t അല്ലെങ്കിൽ s നൽകൂ.',
    err_impossible: 'ഈ മൂല്യങ്ങൾ പരസ്പരം യോജിക്കുന്നില്ല. ചിഹ്നങ്ങൾ (+/−) പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കൂ.',
    err_negt: 'ഈ മൂല്യങ്ങളിൽ സമയം ഋണമാകുന്നു. ചിഹ്നങ്ങൾ പരിശോധിക്കൂ: ഒരുപക്ഷേ a അല്ലെങ്കിൽ s ഋണമാകണം.',
    err_root: 'യഥാർത്ഥ ഉത്തരമില്ല: ഈ മൂല്യങ്ങളിൽ വസ്തു ആ സ്ഥാനാന്തരത്തിൽ എത്തുന്നേയില്ല (v² ഋണമാകുമായിരുന്നു). ചിഹ്നങ്ങൾ പരിശോധിക്കൂ.',
    err_uv0: 'u + v = 0 എന്നാൽ വസ്തു പുറപ്പെട്ടിടത്ത് തന്നെ തിരിച്ചെത്തി (s = 0), അതിനാൽ s-ൽ നിന്ന് സമയം കണ്ടെത്താനാകില്ല. t അല്ലെങ്കിൽ a നൽകൂ.',
    root_note: 'വർഗ്ഗമൂലത്തിന് രണ്ട് ചിഹ്നങ്ങളുണ്ട്. ചലന ദിശയുമായി യോജിക്കുന്നത് ഞങ്ങൾ എടുക്കുന്നു (താഴെ ചിഹ്നങ്ങളെക്കുറിച്ചുള്ള കുറിപ്പ് കാണൂ).',
    sign_note: 'ചിഹ്നങ്ങൾ: ഒരു ദിശ (മുന്നോട്ട് അല്ലെങ്കിൽ മുകളിലേക്ക്) ധനമാണ്. ഋണ പ്രവേഗം എന്നാൽ എതിർ ദിശയിൽ സഞ്ചരിക്കുക. ധന പ്രവേഗത്തോടൊപ്പം ഋണ ത്വരണം എന്നാൽ പതുക്കെയാകുക (മന്ദീകരണം).',
    conv_title: 'km/h ⇄ m/s',
    conv_hint: 'ഏത് വശത്തും ടൈപ്പ് ചെയ്യൂ. 1 m/s = 3.6 km/h, കാരണം 1 km = 1000 m, 1 മണിക്കൂർ = 3600 s.',
    conv_ms: 'm/s', conv_kmh: 'km/h',
    conv_examples: 'ഉപയോഗപ്രദമായ മൂല്യങ്ങൾ: 36 km/h = 10 m/s, 72 km/h = 20 m/s, 90 km/h = 25 m/s, 108 km/h = 30 m/s.',
    deriv_title: 'v–t യുടെ താഴെയുള്ള വിസ്തീർണ്ണം എന്തുകൊണ്ട് സ്ഥാനാന്തരമാകുന്നു?',
    deriv_intro: 'സമ ത്വരണത്തിൽ v–t ഗ്രാഫ് u മുതൽ v വരെയുള്ള ഒരു നേർരേഖയാണ്. അതിന്റെ താഴെയുള്ള വിസ്തീർണ്ണം = ഒരു ദീർഘചതുരം + ഒരു ത്രികോണം:',
    deriv_1: 'ദീർഘചതുരം: വീതി t, ഉയരം u, അതിനാൽ വിസ്തീർണ്ണം u × t (പ്രാരംഭ പ്രവേഗത്തിൽ സഞ്ചരിച്ച ദൂരം).',
    deriv_2: 'ത്രികോണം: പാദം t, ഉയരം (v − u) = at, അതിനാൽ വിസ്തീർണ്ണം ½ × t × at = ½at² (വേഗം കൂടിയതിനാൽ കിട്ടിയ അധിക ദൂരം).',
    deriv_3: 'ആകെ വിസ്തീർണ്ണം = ut + ½at² = s. ഇതാണ് ചലനത്തിന്റെ രണ്ടാം സമവാക്യം.',
    deriv_4: 'ഇതേ ചിത്രം ഒരു ലംബകവുമാണ്; അതിൽ നിന്ന് s = (u + v) ÷ 2 × t കിട്ടുന്നു. അതിൽ t = (v − u) ÷ a ഇട്ടാൽ v² = u² + 2as കിട്ടും.',
    deriv_rect: 'u × t', deriv_tri: '½ × at × t',
    quiz_title: 'ഗ്രാഫ് ക്വിസ്',
