    quiz_good: 'നന്നായി! തെറ്റിയവയുടെ വിശദീകരണം വീണ്ടും വായിക്കൂ.',
    quiz_keep: 'പരിശീലനം തുടരൂ: d–t യുടെ ചരിവ് = വേഗം, v–t യുടെ ചരിവ് = ത്വരണം, v–t യുടെ താഴെയുള്ള വിസ്തീർണ്ണം = ദൂരം.',
