    ws_name: 'പേര്: ____________________   ക്ലാസ്: ________   തീയതി: __________',
    ws_instr: 'ചോദ്യങ്ങൾ 1–3: കഥയുമായി യോജിക്കുന്ന ഗ്രാഫ് ടിക്ക് ചെയ്യൂ. ചോദ്യങ്ങൾ 4–6: ഗ്രാഫ് വായിച്ച് യൂണിറ്റ് സഹിതം ഉത്തരം എഴുതൂ.',
